from abc import ABCMeta, abstractmethod

import attr
import six
from typing import List, Optional  # noqa: F401


@six.add_metaclass(ABCMeta)
class MCS(object):
    """
    MCS, abbreviation of `MIMO Channel System` showed from topyong
    in practice, it is widely used to indicate the devices(not limited to topyoung)
    which both have abilities of programmable attenuator and phases configuration
    """
    @abstractmethod
    def __init__(self, ip_addr, port, mcs_port_numbers, model=None, version=None):
        # type: (str, int, List[int], Optional[str], Optional[str]) -> None
        """

        :param str ip_addr: IP ADDRESS
        :param int port: mcs's port for management
        :param List[int] mcs_port_numbers: List of output port numbers on the mcs
        :param Optional[str] model: model of the mcs, e.g. "MCS2338A2-64B16-A1"
        :param Optional[str] version: version of the mcs
        """
        self.ip_addr = ip_addr
        self.port = port
        self.mcs_ports = {i: MCSPort(self, i) for i in mcs_port_numbers}
        self.model = model
        self.version = version


@attr.s(cmp=False)
class MCSPort(object):
    """

    :param MCS mcs: object of subclass of AttenuationPort
    :param int port_no: Port/Outlet number on the MCS
    """
    mcs = attr.ib(type=MCS)
    port_no = attr.ib(type=int)


class TopYoung(MCS):
    def __init__(self, *args, **kwargs):
        super(TopYoung, self).__init__(*args, **kwargs)
        self.vendor = "TOPYOUNG"


class HBTE(MCS):
    def __init__(self, *args, **kwargs):
        super(HBTE, self).__init__(*args, **kwargs)
        self.vendor = "HBTE"


class HaoJin(MCS):
    def __init__(self, *args, **kwargs):
        super(HaoJin, self).__init__(*args, **kwargs)
        self.vendor = "HAOJIN"
